--
-- Name: guard_confirmation_subject_authority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_confirmation_subject_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF TG_OP = 'UPDATE' AND OLD.bundle_id IS NOT NULL AND ROW(
                NEW.artifact_sha256,
                NEW.base_evidence_sha256,
                NEW.base_quality_micros,
                NEW.base_stderr_micros,
                NEW.base_model_factor_bps,
                NEW.base_tool_factor_bps
            ) IS DISTINCT FROM ROW(
                OLD.artifact_sha256,
                OLD.base_evidence_sha256,
                OLD.base_quality_micros,
                OLD.base_stderr_micros,
                OLD.base_model_factor_bps,
                OLD.base_tool_factor_bps
            ) THEN
                RAISE EXCEPTION 'attached confirmation base proof is immutable'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'confirmation_subject_authority_guard';
            END IF;
            IF NEW.result_status = 'full_confirmed' AND NOT EXISTS (
                SELECT 1 FROM confirmation_bundles bundle
                WHERE bundle.bundle_id = NEW.bundle_id
                  AND bundle.artifact_sha256 = NEW.artifact_sha256
                  AND bundle.bench_version = NEW.bench_version
                  AND bundle.state = 'completed'
                  AND bundle.qualification_status = 'qualified'
                  AND (
                      bundle.completion_mode = 'enforce'
                      OR (
                          bundle.completion_mode = 'shadow'
                          AND EXISTS (
                              SELECT 1
                              FROM confirmation_bundle_settings_revisions current
                              WHERE current.scope = '*'
                                AND current.revision = (
                                    SELECT max(latest.revision)
                                    FROM confirmation_bundle_settings_revisions latest
                                    WHERE latest.scope = '*'
                                )
                                AND current.settings ->> 'mode' = 'enforce'
                                AND current.settings ->> 'profile_revision'
                                    = bundle.profile_revision
                                AND current.settings ->> 'profile_checksum'
                                    = bundle.profile_checksum
                          )
                      )
                  )
            ) THEN
                RAISE EXCEPTION 'full confirmation requires qualified enforce evidence'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'confirmation_subject_authority_guard';
            END IF;
            RETURN NEW;
        END;
        $$;


--
-- Name: guard_efficiency_assignment_curve(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_efficiency_assignment_curve() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        DECLARE
            snapshot_curve integer;
        BEGIN
            IF TG_OP = 'UPDATE' AND (
                OLD.agent_id IS DISTINCT FROM NEW.agent_id
                OR OLD.snapshot_id IS DISTINCT FROM NEW.snapshot_id
                OR OLD.bench_version IS DISTINCT FROM NEW.bench_version
                OR OLD.epoch_index IS DISTINCT FROM NEW.epoch_index
            ) THEN
                RAISE EXCEPTION
                    'efficiency assignment identity is immutable'
                    USING ERRCODE = '23514';
            END IF;

            SELECT curve_version INTO snapshot_curve
              FROM public.efficiency_cohort_snapshots
             WHERE snapshot_id = NEW.snapshot_id
               AND bench_version = NEW.bench_version
               AND epoch_index = NEW.epoch_index;

            IF snapshot_curve IN (3, 4) THEN
                IF TG_OP = 'INSERT' AND NEW.factor IS NULL THEN
                    NEW.bonus := 0;
                ELSIF TG_OP = 'UPDATE' AND OLD.factor IS NOT NULL THEN
                    RAISE EXCEPTION
                        'authoritative efficiency assignment is immutable'
                        USING ERRCODE = '23514';
                ELSIF TG_OP = 'UPDATE' AND NEW.factor IS NOT NULL THEN
                    IF OLD.bonus <> 0 OR NEW.bonus <> 0 THEN
                        RAISE EXCEPTION
                            'only a neutral factor-curve placeholder may be promoted'
                            USING ERRCODE = '23514';
                    END IF;
                ELSIF TG_OP = 'UPDATE' THEN
                    NEW.bonus := 0;
                END IF;
            ELSIF snapshot_curve IS NOT NULL AND NEW.factor IS NOT NULL THEN
                RAISE EXCEPTION
                    'efficiency factor requires a factor-curve snapshot'
                    USING ERRCODE = '23514';
            END IF;
            RETURN NEW;
        END;
        $$;


--
-- Name: guard_efficiency_snapshot_curve(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_efficiency_snapshot_curve() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF TG_OP = 'UPDATE' AND (
                OLD.curve_version >= 3 OR NEW.curve_version >= 3
            ) THEN
                RAISE EXCEPTION
                    'factor-curve efficiency snapshots are immutable'
                    USING ERRCODE = '23514';
            END IF;
            IF TG_OP = 'INSERT'
               AND NEW.bench_version >= 9
               AND NEW.curve_version < 3 THEN
                RAISE EXCEPTION
                    'new bench-v9+ efficiency snapshots require a factor curve'
                    USING ERRCODE = '23514';
            END IF;
            RETURN NEW;
        END;
        $$;


--
-- Name: guard_validator_ticket_bench_floor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_validator_ticket_bench_floor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF NEW.bench_version < 7
               AND (TG_OP = 'INSERT'
                    OR (NEW.status = 'issued'
                        AND (OLD.status <> 'issued'
                             OR NEW.issued_at IS DISTINCT FROM OLD.issued_at
                             OR NEW.deadline > OLD.deadline))) THEN
                RAISE EXCEPTION
                    'benchmark v% is retired and cannot be leased',
                    NEW.bench_version
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'validator_tickets_bench_version_floor';
            END IF;
            RETURN NEW;
        END;
        $$;


--
-- Name: guard_validator_ticket_purpose(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_validator_ticket_purpose() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF NEW.issued_at IS DISTINCT FROM OLD.issued_at
               AND NEW.purpose_revision = OLD.purpose_revision THEN
                NEW.purpose = 'legacy_unclassified';
                NEW.purpose_revision = 0;
                NEW.legacy_completion_allowed = TRUE;
            END IF;
            IF NEW.status = 'scored'
               AND OLD.status IS DISTINCT FROM 'scored'
               AND NEW.purpose_revision = 0
               AND NOT NEW.legacy_completion_allowed THEN
                RAISE EXCEPTION
                    'cannot score an unclassified validator ticket'
                    USING ERRCODE = 'check_violation';
            END IF;
            RETURN NEW;
        END;
        $$;


